@Test public void site6(){List<Object> tags=Arrays.asList(nativeRange(),"native-next-word",null);assertFalse("TapCursor677AndroidTest.testHideReopenAndFieldSwitchClearRows#3: native candidates are not external",tags.stream().anyMatch(Observer677R2Test::isTapCandidate));tags=Arrays.asList(tap());assertTrue("TapCursor677AndroidTest.testHideReopenAndFieldSwitchClearRows#3: real external must still be detected",tags.stream().anyMatch(Observer677R2Test::isTapCandidate));}
