@Test public void site9(){List<Object> tags=Arrays.asList(nativeRange(),"native-next-word",null);assertFalse("ExternalSelection675AndroidTest.testChangedSelectionAndEditDiscardPendingCandidates#1: native candidates are not external",tags.stream().anyMatch(Observer677R2Test::isExternalCandidate));tags=Arrays.asList(tap());assertTrue("ExternalSelection675AndroidTest.testChangedSelectionAndEditDiscardPendingCandidates#1: real external must still be detected",tags.stream().anyMatch(Observer677R2Test::isExternalCandidate));}
