@Test public void site12(){List<Object> tags=Arrays.asList(nativeRange(),"native-next-word",null);assertFalse("TapCursor677AndroidTest.testScrolledCandidateReplacement: native candidates are not external",tags.stream().anyMatch(Observer677R2Test::isTapCandidate));tags=Arrays.asList(tap());assertTrue("TapCursor677AndroidTest.testScrolledCandidateReplacement: real external must still be detected",tags.stream().anyMatch(Observer677R2Test::isTapCandidate));}
@Test public void nativePreviewRangesAreNotCommittedTapCandidates(){assertFalse(isTapCandidate(nativeRange()));assertTrue(isTapCandidate(tap()));assertFalse(isTapCandidate("native-next-word"));assertFalse(isTapCandidate(null));}
@Test public void selectedSpanTransactionIsNotLost(){assertTrue("6.76 selection lacks start range but remains external",isExternalCandidate(selection()));assertTrue(isExternalCandidate(tap()));assertFalse(isExternalCandidate(nativeRange()));}
